// Re-attach the maths generators. build-itembank.mjs strips them (functions do
// not survive JSON) and records the item id; running the same shared module here
// rebuilds them in the same deterministic order, so the ids line up.
(function reattachMathGenerators() {
    const mathTemplates = (typeof window !== 'undefined' && window.mathTemplates) || (typeof globalThis !== 'undefined' && globalThis.mathTemplates);
    if (!mathTemplates) return;
    const rebuilt = {};
    const push = (sub, g, t, it) => {
        rebuilt[sub] = rebuilt[sub] || {};
        rebuilt[sub][g] = rebuilt[sub][g] || { tf: [], single: [], multiple: [] };
        rebuilt[sub][g][t].push(it);
    };
    let uid = 0;
    const nid = (s, g, t) => s + '-' + g + '-' + t + '-' + (++uid).toString(36);
    mathTemplates.buildMath(push, nid);

    Object.keys(rebuilt).forEach(sub => {
        Object.keys(rebuilt[sub]).forEach(g => {
            ['tf', 'single', 'multiple'].forEach(type => {
                const banked = ((ITEM_BANK[sub] || {})[g] || {})[type] || [];
                const byId = {};
                banked.forEach(it => { byId[it.id] = it; });
                (rebuilt[sub][g][type] || []).forEach(it => {
                    if (byId[it.id]) byId[it.id].gen = it.gen;
                });
            });
        });
    });
})();

// One syllable per character; '' for digits, punctuation and Latin script.
function zhuyinOf(text) {
    return Array.from(text).map(ch => ZHUYIN_TABLE[ch] || '').join(' ');
}

// Resolve an item template into a concrete question using the given RNG.
// withZhuyin: only 國小一、二年級 papers (student grade 1-2) get annotations.
function materializeItem(item, rnd, withZhuyin) {
    let base;
    if (item.tpl && typeof item.gen === 'function') {
        base = item.gen(rnd);
    } else {
        base = { q: item.q, options: item.options.slice(), answer: item.answer.slice(), explain: item.explain };
    }
    // Shuffle options and remap the answer indices, so option ORDER is never
    // memorisable either. (是非題 keeps its fixed 是/非 order.)
    if (base.options.length > 2) {
        const idx = base.options.map((_, i) => i);
        for (let i = idx.length - 1; i > 0; i--) {
            const j = Math.floor(rnd() * (i + 1));
            [idx[i], idx[j]] = [idx[j], idx[i]];
        }
        const shuffled = idx.map(i => base.options[i]);
        const answerSet = new Set(base.answer.map(i => idx.indexOf(i)));
        base.options = shuffled;
        base.answer = [...answerSet].sort((a, b) => a - b);
    }
    return {
        id: item.id,
        tpl: !!item.tpl,
        diff: item.diff,
        title: base.q,
        // Annotations are produced only when the student's grade requires them.
        zhuyin: withZhuyin ? zhuyinOf(base.q) : null,
        options: base.options,
        answer: base.answer,
        explanation: base.explain
    };
}

function getItemPool(subject, grade, type) {
    const s = ITEM_BANK[subject];
    if (!s) return [];
    let g = s[grade];
    if (!g) { // fall back to the nearest available grade
        const keys = Object.keys(s).map(Number).sort((a, b) => a - b);
        if (!keys.length) return [];
        const near = keys.reduce((p, c) => Math.abs(c - grade) < Math.abs(p - grade) ? c : p, keys[0]);
        g = s[near];
    }
    return (g && g[type]) ? g[type] : [];
}
